func BenchmarkWorkerPool(b *testing.B) {
	pool := NewWorkerPool(4)
	defer pool.Stop()

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		task := CompilationTask{
			FunctionName: "func",
		}
		pool.Submit(task)
	}
}

